   303→public(package) fun handle_withdraw<MarketType, CoinType>(
   304→    self: &mut Market<MarketType>,
   305→    obligation_id: ID,
   306→    ctoken_amount: u64,
   307→    coin_decimals_registry: &CoinDecimalsRegistry,
   308→    x_oracle: &XOracle,
   309→    clock: &Clock,
   310→    now: u64,
   311→    ctx: &mut TxContext,
   312→): (Coin<CoinType>, u64) {
   313→    assert!(ctoken_amount != 0, error::no_zero_amount());
   314→
   315→    let name = type_name::with_defining_ids<CoinType>();
   316→
   317→    let asset = self.assets.load_by_type(name);
   318→    assert!(!asset.withdraw_paused(), error::withdraw_paused_for_asset());
   319→
   320→
   321→    let obligation = self.obligations.borrow_mut(obligation_id);
   322→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   323→
   324→    // refresh all interest
   325→    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
   326→    refresh_obligation_assets_interest<MarketType>(&self.assets, emode_group, &mut self.reserves, obligation, now);
   327→
   328→    let ctoken = obligation.withdraw_ctokens(ctoken_amount);
   329→    let ctokens_left = obligation.ctoken_amount_by_coin(name);
   330→
   331→    // TODO: if the asset is not collateral, skip obligation safety check
   332→    let is_obligation_safe = is_obligation_safe(
   333→        self.emode_group_registry.borrow_emode_group(obligation.emode_group()),
   334→        &self.reserves,
   335→        &self.ema_spot_tolerance,
   336→
   337→        obligation,
   338→        coin_decimals_registry,
   339→        x_oracle,
   340→        clock,
   341→    );
   342→    assert!(is_obligation_safe, error::obligation_not_safe_after_operation());
   343→
   344→    let reserve = self.reserves.load_mut_by_type(name);
   345→    let deposit = reserve.burn_ctokens<MarketType, CoinType>(ctoken.into_coin(ctx));
   346→
   347→    // rate limit deposit withdraw
   348→    let emode = self.emode_group_registry.borrow_mut_emode(obligation.emode_group(), type_name::with_defining_ids<CoinType>());
   349→    emode.borrow_mut_deposit_limiter().add_outflow(
   350→        now,
   351→        deposit.value(),
   352→    );
   353→
   354→    // update adl
   355→
   356→    // use ceiling, slighly more 
   357→    let total_deposit = reserve.total_deposit_plus_interest().ceil();
   358→    let adl = dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {});
   359→    adl.try_stop_collateral_deleverage<CoinType>(type_name::with_defining_ids<MarketType>(), total_deposit);
   360→
   361→
   362→
   363→    (deposit.into_coin(ctx), ctokens_left)
   364→}
