  1015→fun accrue_interest<MarketType>(
  1016→    coin_type: TypeName,
  1017→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
  1018→    asset: &AssetConfig,
  1019→    interest_model: &InterestModel,
