     1→module protocol::asset;
     2→
     3→use math::float::Decimal;
     4→use protocol::interest::InterestModel;
     5→use std::option::some;
     6→use sui::dynamic_field;
     7→use protocol::error;
     8→
     9→public struct AssetConfig has copy, drop, store {
    10→    /********
    11→    when the principal and ratio of borrow indices are both small,
    12→    the result can equal the principal, due to automatic truncation of division
    13→    newDebt = debt * (current borrow index) / (original borrow index)
    14→    so that the user could borrow without interest
    15→    *********/
    16→    min_borrow_amount: u64,
    17→    /// max amount this asset can be borrow across the market
    18→    max_borrow_amount: u64,
    19→    /// max amount this asset can be deposited across the market
    20→    max_deposit_amount: u64,
    21→    /// fee rate paid to the protocol in repay
    22→    repay_fee_rate: Decimal,
    23→
    24→    liquidation_fee_rate: Decimal,
    25→}
    26→
    27→public struct Asset<phantom MarketType> has key, store {
    28→    id: UID,
    29→    // Indicates when flash loan is in progress
    30→    flash_loan_lock: bool,
    31→    interest_model: InterestModel,
    32→    // dynamic fields:
    33→    // - borrow: Option<AssetConfig>
    34→    // - borrow_paused: bool,
    35→    // - deposit_paused: bool,
    36→    // - withdraw_paused: bool,
    37→    // - liquidation_paused: bool,
    38→    // - flash_loan_paused: bool,
    39→}
    40→
    41→
    42→// =============== Getter Functions =============
    43→public fun flash_loan_ongoing<MarketType>(self: &Asset<MarketType>): bool { self.flash_loan_lock }
    44→
    45→public fun borrow_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<BorrowPaused, bool>(&self.id, BorrowPaused {}) }
    46→public fun deposit_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<DepositPaused, bool>(&self.id, DepositPaused {}) }
    47→public fun withdraw_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<WithdrawPaused, bool>(&self.id, WithdrawPaused {}) }
    48→public fun liquidation_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<LiquidationPaused, bool>(&self.id, LiquidationPaused {}) }
    49→public fun flash_loan_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<FlashLoanPaused, bool>(&self.id, FlashLoanPaused {}) }
    50→
    51→public fun min_borrow_amount(self: &AssetConfig): u64 { self.min_borrow_amount }
    52→public fun max_borrow_amount(self: &AssetConfig): u64 { self.max_borrow_amount }
    53→public fun max_deposit_amount(self: &AssetConfig): u64 { self.max_deposit_amount }
    54→public fun repay_fee_rate(self: &AssetConfig): Decimal { self.repay_fee_rate }
    55→public fun liquidation_fee_rate(self: &AssetConfig): Decimal { self.liquidation_fee_rate }
    56→
    57→
    58→public(package) fun asset_config<MarketType>(self: &Asset<MarketType>): &AssetConfig {
    59→    dynamic_field::borrow<DFKey<AssetConfig>, Option<AssetConfig>>(
    60→        &self.id,
    61→        DFKey<AssetConfig> {},
    62→    ).borrow()
    63→}
    64→
    65→public(package) fun interest_model<MarketType>(self: &Asset<MarketType>): &InterestModel {
    66→    &self.interest_model
    67→}
    68→
    69→// ================= Constructor ================
    70→public(package) fun new<MarketType>(
    71→    interest_model: InterestModel,
    72→    borrow: AssetConfig,
    73→    ctx: &mut TxContext,
    74→): Asset<MarketType> {
    75→    let mut asset = Asset {
    76→        id: object::new(ctx),
    77→        flash_loan_lock: false,
    78→        interest_model,
    79→    };
    80→
    81→    dynamic_field::add(&mut asset.id, DFKey<AssetConfig> {}, some<AssetConfig>(borrow));
    82→
    83→    dynamic_field::add(&mut asset.id, BorrowPaused {}, false);
    84→    dynamic_field::add(&mut asset.id, DepositPaused {}, false);
    85→    dynamic_field::add(&mut asset.id, WithdrawPaused {}, false);
    86→    dynamic_field::add(&mut asset.id, LiquidationPaused {}, false);
    87→    dynamic_field::add(&mut asset.id, FlashLoanPaused {}, false);
    88→
    89→    asset
    90→}
    91→
    92→/// Create a new shared asset configuration across all emodes in a market
    93→public(package) fun new_asset_config(
    94→    min_borrow_amount: u64,
    95→    max_borrow_amount: u64,
    96→    repay_fee_rate: Decimal,
    97→    max_deposit_amount: u64,
    98→    liquidation_fee_rate: Decimal,
    99→): AssetConfig {
   100→    AssetConfig {
   101→        min_borrow_amount,
   102→        max_borrow_amount,
   103→        repay_fee_rate,
   104→        max_deposit_amount,
   105→        liquidation_fee_rate,
   106→    }
   107→}
   108→
   109→public(package) fun update_interest_model<MarketType>(
   110→    self: &mut Asset<MarketType>,
   111→    model: InterestModel,
   112→) {
   113→    self.interest_model = model;
   114→}
   115→
   116→fun assert_not_equal_and_set<Name: copy + drop + store>(id: &mut UID, name: Name, v: bool) {
   117→    let current = dynamic_field::borrow_mut<Name, bool>(id, name);
   118→    assert!(*current != v, error::updating_with_same_value());
   119→    *current = v;
   120→}
   121→
