#[test_only]
module protocol::repay_test {

  use sui::test_scenario;
  use sui::clock;

  use protocol::market_t::MainMarket;
  use protocol::oracle_t;
  use test_coin::eth::ETH;
  use protocol::open_obligation_t;
  use test_coin::usdc::USDC;
  use sui::coin::Coin;
  use std::type_name;
  use protocol::market_t::default_eth_decimal_places;
  use protocol::market_t::default_stable_decimal_places;

  const ADMIN: address = @0xAD;

  #[test]
  public fun repay_equal_debt_test() {
    let mut scenario_value = test_scenario::begin(ADMIN);
    let scenario = &mut scenario_value;
    let mut clock = clock::create_for_testing(scenario.ctx());

    let (admin_cap, mut app, mut market, coin_registry) = protocol::app_t::default_app_init<MainMarket>(
        scenario, 
        &mut clock, 
        ADMIN,
    );
    let mut x_oracle = oracle_t::init_t(scenario);
    clock.set_for_testing(200 * 1000);
    x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

    let lender = @0xAA;
    let borrower = @0xBB;

    test_scenario::next_tx(scenario, borrower);
    let eth_amount = 2 * 10u64.pow(default_eth_decimal_places());
    let eth_coin = sui::coin::mint_for_testing<ETH>(eth_amount, test_scenario::ctx(scenario));
    let obligation_owner_cap = open_obligation_t::open_obligation_t<MainMarket>(scenario, &app, &mut market);
    protocol::deposit::deposit<MainMarket, ETH>(&app, &mut market, &obligation_owner_cap, eth_coin, &clock, scenario.ctx());

    clock.set_for_testing(300 * 1000);
    x_oracle.update_price<USDC>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1
    x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

    test_scenario::next_tx(scenario, borrower);
    let borrow_amount = 699 * 10u64.pow(default_stable_decimal_places());
    let borrowed = protocol::borrow::borrow<MainMarket, USDC>(&app, &obligation_owner_cap, &mut market, &coin_registry, borrow_amount, &x_oracle, &clock, scenario.ctx());
    assert!(borrowed.value() == borrow_amount, 0);
    std::unit_test::destroy(borrowed);

    // mint more
    test_scenario::next_tx(scenario, lender);
    // does not trigger interest update because the clock has not advanced
    protocol::market_t::increase_deposit<MainMarket, USDC>(&mut app, &mut market, &coin_registry, &x_oracle, &clock, scenario, 10u64.pow(default_stable_decimal_places() + 4));

    // trigger interest compound
    clock.set_for_testing(666 * 1000);
    protocol::market_t::increase_deposit<MainMarket, USDC>(&mut app, &mut market, &coin_registry, &x_oracle, &clock, scenario, 10u64.pow(default_stable_decimal_places() + 4));

    // borrow more
    clock::set_for_testing(&mut clock, 1500 * 1000);
    // refresh price feed
    x_oracle.update_price<USDC>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1
    x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

    test_scenario::next_tx(scenario, borrower);
    let borrow_amount = 699 * 10u64.pow(default_stable_decimal_places());
    let borrowed = protocol::borrow::borrow<MainMarket, USDC>(&app, &obligation_owner_cap, &mut market, &coin_registry, borrow_amount, &x_oracle, &clock, scenario.ctx());
    assert!(borrowed.value() == borrow_amount, 0);

    let reserve = market.get_reserve<MainMarket, USDC>();
    let (debt_amount, borrow_index) = market.borrow_obligation(obligation_owner_cap.id()).debt(std::type_name::with_defining_ids<USDC>()).snapshot();
    // make sure both liquidation and reserve already updated to the latest borrow_index so the debt data is the latest one
    assert!(borrow_index == reserve.borrow_index().value());
    // *********************************************************
    // this line has some slight descripency in accuracy due to floating point precision
    // the error comes from the two interest compound: one from increase_deposit and one from previous borrow.
    // so reserve.debt has went through two Decimal multiplications.
    // Meanwhile, obligation has only gone through just one Decimal multiplication from the borrow. The multiplication
    // is done with the latest reserve borrow index divided by the previous obligation.borrow_index. So the obligation multiplication
    // is the outcome of two reserve multiplications, causing slight drift in results.
    assert!((*reserve.debt()).sub(debt_amount).div(debt_amount).lt(math::float::from_quotient(1, 10u64.pow(10))));
    // *********************************************************

    let repay_amount = debt_amount.floor();
    let usdc_coin = sui::coin::mint_for_testing<USDC>(repay_amount, test_scenario::ctx(scenario));
    protocol::repay::repay<MainMarket, USDC>(&app, &obligation_owner_cap, &mut market, usdc_coin, &clock, test_scenario::ctx(scenario));

    let obligation = market.borrow_obligation(obligation_owner_cap.id());
    assert!(!obligation.debt_types().contains(&type_name::with_defining_ids<USDC>()));

    clock::destroy_for_testing(clock);

    test_scenario::return_shared(x_oracle);
    test_scenario::return_shared(market);


    std::unit_test::destroy(borrowed);
    std::unit_test::destroy(admin_cap);
    std::unit_test::destroy(obligation_owner_cap);
    std::unit_test::destroy(app);
    std::unit_test::destroy(coin_registry);
    test_scenario::end(scenario_value);
  }

  #[test]
  public fun repay_with_refund_test() {
    // borrower repay more than owned after interest added, the extra should be refunded
    let mut scenario_value = test_scenario::begin(ADMIN);
    let scenario = &mut scenario_value;
    let mut clock = clock::create_for_testing(scenario.ctx());

    let (admin_cap, mut app, mut market, coin_registry) = protocol::app_t::default_app_init<MainMarket>(
        scenario, 
        &mut clock, 
        ADMIN,
    );
    let mut x_oracle = oracle_t::init_t(scenario);

    clock.set_for_testing(200 * 1000);
    x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

    let lender = @0xAA;
    let borrower = @0xBB;

    test_scenario::next_tx(scenario, borrower);
    let eth_amount = 2 * 10u64.pow(default_eth_decimal_places());
    let eth_coin = sui::coin::mint_for_testing<ETH>(eth_amount, test_scenario::ctx(scenario));
    let obligation_owner_cap = open_obligation_t::open_obligation_t<MainMarket>(scenario, &app, &mut market);
    protocol::deposit::deposit<MainMarket, ETH>(&app, &mut market, &obligation_owner_cap, eth_coin, &clock, scenario.ctx());

    clock.set_for_testing(300 * 1000);
    x_oracle.update_price<USDC>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1
    x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

    test_scenario::next_tx(scenario, borrower);
    let borrow_amount = 699 * 10u64.pow(default_stable_decimal_places());
    let borrowed = protocol::borrow::borrow<MainMarket, USDC>(&app, &obligation_owner_cap, &mut market, &coin_registry, borrow_amount, &x_oracle, &clock, scenario.ctx());
    assert!(borrowed.value() == borrow_amount, 0);
    std::unit_test::destroy(borrowed);

    // mint more and trigger interest compound
    test_scenario::next_tx(scenario, lender);
    protocol::market_t::increase_deposit<MainMarket, USDC>(&mut app, &mut market, &coin_registry, &x_oracle, &clock, scenario, 10u64.pow(default_stable_decimal_places() + 4));

    // borrow more
    clock::set_for_testing(&mut clock, 1500 * 1000);
    // refresh price feed
    x_oracle.update_price<USDC>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1
    x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

    test_scenario::next_tx(scenario, borrower);
    let borrow_amount = 699 * 10u64.pow(default_stable_decimal_places());
    let borrowed = protocol::borrow::borrow<MainMarket, USDC>(&app, &obligation_owner_cap, &mut market, &coin_registry, borrow_amount, &x_oracle, &clock, scenario.ctx());
    assert!(borrowed.value() == borrow_amount, 0);

    clock.set_for_testing(2500 * 1000);
    x_oracle.update_price<USDC>(&clock, oracle_t::calc_scaled_price(1, 0)); // $1
    x_oracle.update_price<ETH>(&clock, oracle_t::calc_scaled_price(1000, 0)); // $1000

    protocol::market_t::increase_deposit<MainMarket, USDC>(&mut app, &mut market, &coin_registry, &x_oracle, &clock, scenario, 10u64.pow(default_stable_decimal_places() + 4));

    let (debt_amount, _) = market.borrow_obligation(obligation_owner_cap.id()).debt(std::type_name::with_defining_ids<USDC>()).snapshot();
    let repay_amount = debt_amount.mul_u64(2);

    let actual_repay_amount = debt_amount.ceil();

    test_scenario::next_tx(scenario, borrower);
    let usdc_coin = sui::coin::mint_for_testing<USDC>(repay_amount.floor(), test_scenario::ctx(scenario));
    protocol::repay::repay<MainMarket, USDC>(&app, &obligation_owner_cap, &mut market, usdc_coin, &clock, test_scenario::ctx(scenario));

    test_scenario::next_tx(scenario, borrower);
    let refunded = scenario.take_from_sender<Coin<USDC>>();

    let expected_refund = repay_amount.floor() - actual_repay_amount;

    assert!(refunded.value() == expected_refund);
    std::unit_test::destroy(refunded);

    let reserve = market.get_reserve<MainMarket, USDC>();
    let obligation = market.borrow_obligation(obligation_owner_cap.id());
    assert!(obligation.debt_types().is_empty());
    assert!(reserve.debt<MainMarket>().is_zero());

    // ensure can deposit after repay all    
    let usdc_coin = sui::coin::mint_for_testing<USDC>(100000000, test_scenario::ctx(scenario));
    protocol::deposit::deposit(&app, &mut market, &obligation_owner_cap, usdc_coin, &clock, scenario.ctx());

    clock::destroy_for_testing(clock);

    test_scenario::return_shared(x_oracle);
    test_scenario::return_shared(market);

    std::unit_test::destroy(borrowed);
    std::unit_test::destroy(admin_cap);
    std::unit_test::destroy(obligation_owner_cap);
    std::unit_test::destroy(app);
    std::unit_test::destroy(coin_registry);
    test_scenario::end(scenario_value);
  }

